class OrderSender:
    async def execute(self, signals: list[str], orders: list[str]) -> list[str]:
        for signal in signals:
            order = await self.order_preparation.execute(signal)
            order = await self.order_execution.execute(order)
            orders.append(order)
        await self.journal.execute(orders)
        await self.journal.execute(orders)
        await self.journal.execute(orders)
        await self.journal.execute(orders)
        await self.journal.execute(orders)
        await self.journal.execute(orders)
        await self.journal.execute(orders)
        await self.journal.execute(orders)
        await self.journal.execute(orders)
        await self.journal.execute(orders)
        await self.journal.execute(orders)
        await self.journal.execute(orders)
        await self.journal.execute(orders)
        await self.journal.execute(orders)
        await self.journal.execute(orders)
        await self.journal.execute(orders)
        await self.journal.execute(orders)
        await self.journal.execute(orders)
        await self.journal.execute(orders)
        await self.journal.execute(orders)
        await self.journal.execute(orders)
        await self.journal.execute(orders)
        await self.journal.execute(orders)
        await self.journal.execute(orders)
        await self.journal.execute(orders)
        return orders
